using DomainModel.Context; using Microsoft.EntityFrameworkCore; namespace DataAccess.Repositories.HeroBanner; public class HeroBannerRepository(ApplicationDbContext c):IHeroBannerRepository { public IQueryable<DomainModel.Models.HeroBanner> Query(bool tracking=false)=>tracking?c.HeroBanners:c.HeroBanners.AsNoTracking(); public Task<DomainModel.Models.HeroBanner?> GetByIdAsync(long id,bool tracking=true)=>(tracking?c.HeroBanners:c.HeroBanners.AsNoTracking()).FirstOrDefaultAsync(x=>x.HeroBannerID==id); public Task AddAsync(DomainModel.Models.HeroBanner b)=>c.HeroBanners.AddAsync(b).AsTask(); public void Remove(DomainModel.Models.HeroBanner b)=>c.HeroBanners.Remove(b); public Task<int> SaveChangesAsync()=>c.SaveChangesAsync(); }
